export class CalculoTarifaHelper{constructor(){}requiredParam(param){throw new Error(`Falta el parámetro requerido: ${param}`)}static calcularPrecioConIva(precioVenta,porcentaje){try{const resultadoPorcentaje=Number(porcentaje)/100,result=Number(precioVenta)*Number(resultadoPorcentaje),precioConIva=result+Number(precioVenta);return precioConIva}catch(error){toastr.error(error)}}static calcularPrecioVenta(precioConIva,porcentaje){try{const resultadoPorcentaje=Number(porcentaje)/100+1,precioVenta=Number(precioConIva)/Number(resultadoPorcentaje);return precioVenta}catch(error){toastr.error(error)}}static calcularPorcentajeUtilidad(precioCosto,porcentajeUtilidad){try{let resultPorcentajeUtilidad=Number(porcentajeUtilidad)/100,result=Number(precioCosto)*resultPorcentajeUtilidad,precioVenta;return Number(precioCosto)+result}catch(error){toastr.error(error)}}static campoPorcentajeUtilidad(precioCosto,precioVenta){try{let porcentajeUtilidad;return Number(precioVenta)/Number(precioCosto)*100-100}catch(error){toastr.error(error)}}static getPrecioIvaConDescuento(precioConIva,porcentajeDescuento){try{let porcentaje=Number(porcentajeDescuento)/100,descuento=Number(porcentaje)*Number(precioConIva),precioIvaConDescuento;return Number(precioConIva)-Number(descuento)}catch(error){toastr.error("CÁLCULO DE PRECIO CON IVA CON DESCUENTO")}}static getValorDescuento(precioUnitario,porcentajeDescuento){try{let porcentaje=Number(porcentajeDescuento)/100,descuento;return Number(porcentaje)*Number(precioUnitario)}catch(error){toastr.error(`CÁLCULO DE VALOR DESCUENTO: ${error}`)}}static getPorcentajeDescuento(precioUnitario,valorDescuento){let porcentaje,porcentajeDescuento;return 100*(valorDescuento/precioUnitario)}}